"""What an agent's pull request may change (ADR-0018).

Agents deliver datasets: contracts and gold models. Everything that decides
whether a pipeline is correct (blocks, generated tests, CI, adapters, naming
configuration) is out of their reach, so they cannot weaken it to pass.
"""

from fnmatch import fnmatch

AGENT_ALLOWED = (
    "contracts/*/*.yaml",
    "pipelines/*/gold/*.yaml",
    "pipelines/*/gold/*.sql",
    "infra/airflow/dags/*.py",  # regenerated by `contractline dags`, checked by CI
    "evaluation/logs/*.jsonl",  # the agent's own work log
)


def is_agent_branch(branch: str) -> bool:
    return branch.startswith("agent/")


def _matches(path: str, pattern: str) -> bool:
    """Glob match where ``*`` never crosses a ``/``."""
    parts, wanted = path.split("/"), pattern.split("/")
    return len(parts) == len(wanted) and all(
        fnmatch(part, glob) for part, glob in zip(parts, wanted, strict=True)
    )


def find_out_of_scope(branch: str, changed_files: list[str]) -> list[str]:
    """Files an agent branch changed but may not. Humans are not restricted here
    (CODEOWNERS decides who must review their changes)."""
    if not is_agent_branch(branch):
        return []
    return [
        path
        for path in changed_files
        if path.strip() and not any(_matches(path.strip(), pattern) for pattern in AGENT_ALLOWED)
    ]
